import{_ as t,o,c as a,a3 as d}from"./chunks/framework.BTQ4eCVb.js";const p=JSON.parse('{"title":"Knowledge Base Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Knowledge Base Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/knowledge-base-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Knowledge Base Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/knowledge-base-overview"}]]},"headers":[],"relativePath":"user-guide/knowledge-base-overview.md","filePath":"user-guide/knowledge-base-overview.md","lastUpdated":1787517118000}'),l={name:"user-guide/knowledge-base-overview.md"};function i(r,e,s,n,c,u){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="knowledge-base-module" tabindex="-1">Knowledge Base Module <a class="header-anchor" href="#knowledge-base-module" aria-label="Permalink to &quot;Knowledge Base Module&quot;">​</a></h1><p>Free Operations Marketplace module for <strong>internal</strong> team help articles, categories, and searchable FAQs. Catalog version <strong>1.1.0</strong>. There is no public or customer portal in v1.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/knowledge-base">knowledge-base.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/knowledge-base">knowledge-base.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/knowledge-base">knowledge-base.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-knowledge-base">tenant-v1-knowledge-base.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Articles: title, slug, excerpt, TipTap HTML body, optional category, status (<code>draft</code> / <code>published</code> / <code>archived</code>), <code>published_at</code></li><li>Flat categories (delete blocked while articles still use them)</li><li>Search across title, excerpt, and body; status and trash filters for editors</li><li>Soft <strong>Help Desk</strong> backlinks on article show when <code>help-desk</code> is entitled (<code>help_desk_tickets</code> on <code>GET /knowledge-base/{id}</code>)</li><li>Optional <strong>article attachments</strong> on create/edit (counts toward <a href="/user-guide/storage-overview">Storage</a> quota)</li><li>Notes + domain timeline; Spatie <code>LogsActivity</code> + platform audit events</li><li>Module licensing (<code>module:knowledge-base</code>) for install; Spatie permissions for all access</li><li>Internal workspace only — no public URLs or customer portal</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>knowledge-base.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code></p><p>Default roles: <strong>admin</strong> = all except <code>force.delete</code>; <strong>manager</strong> = view / create / update; <strong>staff</strong> = view.</p><p>View-only users see <strong>published</strong> articles only. Users with <code>knowledge-base.update</code> can open drafts, archived, and trash.</p><h2 id="catalog" tabindex="-1">Catalog <a class="header-anchor" href="#catalog" aria-label="Permalink to &quot;Catalog&quot;">​</a></h2><ul><li>Slug: <code>knowledge-base</code></li><li>Category: Operations (<code>operations</code>, sort <code>40</code>), module sort <code>60</code>, icon <code>book-open</code></li><li><code>is_default_included=false</code>, <code>is_billable=false</code>, prices <code>$0</code></li><li>Install from Marketplace (not auto-installed for new workspaces)</li><li>No hard module dependencies</li></ul><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Public / customer-facing URLs</li><li>Nested categories</li><li>Dashboard widget</li><li>Automation triggers</li><li>Publish notification fan-out</li></ul>',14)])])}const m=t(l,[["render",i]]);export{p as __pageData,m as default};
